INSERT INTO feature VALUES('obligation-report','workflow','How the pull request obligations are answered',NULL,'implemented','ordinary',NULL,'Each night `report:obligations` reads the month''s merged pull requests and the unit issues they close through the same section reader the checks use, and writes five tables on one `report: obligations, <month>` issue, the lane as the row and the ISO week as the column: the Concerns marked `no`, the Sources read dispositions, the Readings selected and answered at a site, the Refactoring verdicts and the Ledger rows moved. No figure is a gate; the previous month''s issue closes with its last full update.',NULL,'.config/reports/obligations.json',NULL,NULL);
